// Даты подставляются на лету: календарь с зашитым числом
// протух бы назавтра и проверял бы не то.
const pad = (n) => String(n).padStart(2, '0');
const now = new Date();
const d = (offset) => {
  const x = new Date(now);
  x.setDate(x.getDate() + offset);
  return `${x.getFullYear()}${pad(x.getMonth() + 1)}${pad(x.getDate())}`;
};
const ics = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//HELM//Тестовый календарь//RU',
  'BEGIN:VEVENT',
  'UID:helm-test-1@cmpas.ru',
  `DTSTART;TZID=Europe/Moscow:${d(0)}T100000`,
  'SUMMARY:Созвон по проекту',
  'END:VEVENT',
  'BEGIN:VEVENT',
  'UID:helm-test-2@cmpas.ru',
  `DTSTART;TZID=Europe/Moscow:${d(0)}T150000`,
  'SUMMARY:Забрать анализы',
  'END:VEVENT',
  'BEGIN:VEVENT',
  'UID:helm-test-3@cmpas.ru',
  `DTSTART;VALUE=DATE:${d(1)}`,
  'SUMMARY:Завтрашнее событие — в сегодняшний план попасть не должно',
  'END:VEVENT',
  'END:VCALENDAR',
].join('\r\n');
return [{ json: { data: ics } }];
